def floodFill(image, sr, sc, color):
    orig = image[sr][sc]
    if orig == color:
        return image
    R, C = len(image), len(image[0])
    st = [(sr, sc)]
    image[sr][sc] = color
    while st:
        r, c = st.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and image[nr][nc] == orig:
                image[nr][nc] = color
                st.append((nr, nc))
    return image

