from collections import deque
def floodFill(image, sr, sc, color):
    R, C = len(image), len(image[0])
    orig = image[sr][sc]
    seen = {(sr, sc)}
    q = deque([(sr, sc)])
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in seen and image[nr][nc] == orig:
                seen.add((nr, nc))
                q.append((nr, nc))
    for r, c in seen:
        image[r][c] = color
    return image

