def floodFill(image, sr, sc, color):
    orig = image[sr][sc]
    if orig == color:
        return image
    R, C = len(image), len(image[0])
    def dfs(r, c):
        if r < 0 or c < 0 or r >= R or c >= C or image[r][c] != orig:
            return
        image[r][c] = color
        dfs(r + 1, c); dfs(r - 1, c); dfs(r, c + 1); dfs(r, c - 1)
    dfs(sr, sc)
    return image
